272	// htmlCommentStart returns the index in s, from from on, of the next "<!--"
273	// that opens an HTML comment, or -1. One written in inline code (an odd
274	// number of backticks before it on its line) opens nothing: Markdown shows
275	// it as text, as a spec that names the marker does (review of
276	// pose-review-declared-limits-followups: its own R2 named it).
277	func htmlCommentStart(s string, from int) int {
278		for {
279			k := strings.Index(s[from:], "<!--")
280			if k < 0 {
281				return -1
282			}
283			k += from
284			lineStart := strings.LastIndex(s[:k], "\n") + 1
285			if strings.Count(s[lineStart:k], "`")%2 == 0 {
286				return k
287			}
288			from = k + 4
289		}
290	}
