292	// visibleOutsideComments returns what of line Markdown shows outside HTML
293	// comments, and whether a comment is still open after it.
294	func visibleOutsideComments(line string, inComment bool) (string, bool) {
295		var visible strings.Builder
296		rest := line
297		for rest != "" {
298			if inComment {
299				end := strings.Index(rest, "-->")
300				if end < 0 {
301					return visible.String(), true
302				}
303				rest = rest[end+3:]
304				inComment = false
305				continue
306			}
307			start := htmlCommentStart(rest, 0)
308			if start < 0 {
309				visible.WriteString(rest)
310				break
311			}
312			visible.WriteString(rest[:start])
313			rest = rest[start+4:]
314			inComment = true
315		}
316		return visible.String(), inComment
317	}
